from typing import Any
from typing import TextIO
import csv
import io
import os

REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def xlsx_to_csv_text(path_or_file: Any) -> str:
    """Convert the first sheet of an .xlsx workbook to CSV text.

    One CSV line is emitted per sheet row (embedded newlines are flattened),
    so reported row numbers match the spreadsheet's row numbers.
    """
    from openpyxl import load_workbook

    workbook = load_workbook(path_or_file, read_only=True, data_only=True)
    try:
        sheet = workbook.worksheets[0]
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator='\n')
        for cells in sheet.iter_rows(values_only=True):
            writer.writerow([
                '' if cell is None else str(cell).replace('\r', ' ').replace('\n', ' ')
                for cell in cells
            ])
        return buffer.getvalue()
    finally:
        workbook.close()


def validate_user_upload(file_path: str, max_rows: int = MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users export (.xlsx or .csv).

    Every row is checked (required fields, email format, duplicate emails,
    age) and all problems are collected instead of stopping at the first one.

    Returns:
        {
            "valid_users": [{"name", "email", "age"}, ...],
            "invalid_rows": [{"row": <1-based row/line number>, "errors": [reasons]}, ...],
            "total_valid": int,
            "total_invalid": int,
        }
    A file-level problem (unsupported type, unreadable file, missing columns)
    is reported as a single invalid entry rather than raised.
    """
    extension = os.path.splitext(file_path)[1].lower()
    try:
        if extension == '.xlsx':
            text = xlsx_to_csv_text(file_path)
        elif extension == '.csv':
            with open(file_path, 'r', encoding='utf-8-sig', newline='') as handle:
                text = handle.read()
        else:
            return _file_level_error(f'unsupported file type "{extension or "none"}"; use .xlsx or .csv')
    except UnicodeDecodeError:
        return _file_level_error('file is not valid UTF-8 text')
    except ImportError:
        return _file_level_error('xlsx support requires the openpyxl package')
    except Exception:
        return _file_level_error('file could not be read; it may be corrupt or not a valid spreadsheet')

    valid_users, invalid_rows = import_users(text, max_rows=max_rows)
    invalid_rows = sorted(invalid_rows, key=lambda problem: problem['row'])
    return {
        'valid_users': valid_users,
        'invalid_rows': invalid_rows,
        'total_valid': len(valid_users),
        'total_invalid': len(invalid_rows),
    }


def _file_level_error(message: str) -> dict[str, Any]:
    return {
        'valid_users': [],
        'invalid_rows': [{'row': 1, 'errors': [message]}],
        'total_valid': 0,
        'total_invalid': 1,
    }

